# POST /api/sheets/{sheetId}/archive — archive the sheet: it stays visible and every change to it is refused from then
# on (see ViewerGuard). Only a steward may archive; a user who is not a steward, or a sheet already archived, is a 400
# and writes nothing. Responds with the sheet as stored.
validate:
  class: net.officefloor.hq.app.sheet.ValidateArchive
  next: archive
archive:
  class: net.officefloor.hq.app.sheet.ArchiveSheet
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.sheet.RecordSheetArchived
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
# GET /api/sheets/{sheetId} — the sheet as the store holds it now. An id never used before is an
# empty sheet; loading it writes nothing but that it has been loaded (it then exists, see parent).
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: loaded
loaded:
  class: net.officefloor.hq.app.sheet.RecordSheetLoaded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.sheet.RespondWithSheet
package net.officefloor.hq.app.sheet;

/** Body of archiving a sheet: who archives it. */
public record ArchiveRequest(String by) {
}
package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Archives the sheet. Only a steward may archive; archiving a sheet already archived is refused. */
public class ArchiveSheet {
    public void archive(@PathVariable("sheetId") String sheetId, @Val ArchiveRequest request, SheetRepository sheets,
            RoleRepository roles, Out<Sheet> sheet) throws InvalidArchiveException {
        String id = sheetId.trim();
        if (!RoleRepository.STEWARD.equals(roles.roleOf(id, request.by()))) {
            throw new InvalidArchiveException("Only a steward may archive the sheet");
        }
        if (!sheets.archive(id, request.by())) {
            throw new InvalidArchiveException("The sheet is already archived");
        }
        sheet.set(sheets.find(id));
    }
}
