package net.officefloor.hq.app.role;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import jakarta.servlet.http.HttpServletResponse;
import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.Ordered;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A viewer changes nothing: every change to a sheet (any non-GET request under {@code /api/sheets/<id>/}) made
 * by a user whose role on that sheet is viewer is refused (403) before it reaches its endpoint, so nothing is
 * stored and nothing audited. So is every change, by anyone, to a sheet a steward archived, and every change made from
 * a screen showing the sheet as of a date (it carries the {@code X-As-Of} header, see AsOf). A bulk action instead goes
 * through with nothing done: 0 done, every selected claim refused (a bulk grade: 0 people changed; a bulk retire: 0 people retired).
 */
@Configuration
public class ViewerGuard {

    private static final Pattern SHEET_PATH = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");
    private static final ObjectMapper JSON = new ObjectMapper();

    @Bean
    public FilterRegistrationBean<OncePerRequestFilter> viewerGuardFilter(RoleRepository roles, SheetRepository sheets) {
        FilterRegistrationBean<OncePerRequestFilter> registration = new FilterRegistrationBean<>(new Filter(roles, sheets));
        registration.addUrlPatterns("/api/*");
        registration.setOrder(Ordered.HIGHEST_PRECEDENCE);
        return registration;
    }

    private static final class Filter extends OncePerRequestFilter {
        private final RoleRepository roles;
        private final SheetRepository sheets;

        Filter(RoleRepository roles, SheetRepository sheets) {
            this.roles = roles;
            this.sheets = sheets;
        }

        @Override
        protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
                throws ServletException, IOException {
            String method = request.getMethod();
            Matcher m = SHEET_PATH.matcher(request.getRequestURI());
            if ("GET".equals(method) || "HEAD".equals(method) || "OPTIONS".equals(method) || !m.matches()) {
                chain.doFilter(request, response);
                return;
            }
            String sheetId = URLDecoder.decode(m.group(1), StandardCharsets.UTF_8).trim();
            String rest = m.group(2) == null ? "" : m.group(2);
            byte[] body = request.getInputStream().readAllBytes();
            JsonNode json = parse(body);
            String by = json != null && json.hasNonNull("by") ? json.get("by").asText().trim() : "";
            boolean viewer = RoleRepository.VIEWER.equals(roles.roleOf(sheetId, by));
            boolean archived = sheets.archived(sheetId);
            String asOf = request.getHeader(AsOf.HEADER);
            boolean viewingAsOf = asOf != null && !asOf.isBlank();
            if (!viewer && !archived && !viewingAsOf) {
                chain.doFilter(new Replay(request, body), response);
                return;
            }
            if (rest.equals("/bulk-open") || rest.equals("/bulk-settle")) {
                int selected = json != null && json.get("claimIds") != null && json.get("claimIds").isArray()
                        ? json.get("claimIds").size()
                        : 0;
                String done = rest.equals("/bulk-open") ? "opened" : "settled";
                response.setStatus(HttpServletResponse.SC_OK);
                response.setContentType("application/json");
                response.setCharacterEncoding("UTF-8");
                response.getWriter().write("{\"" + done + "\":0,\"refused\":" + selected + "}");
                return;
            }
            if (rest.equals("/bulk-grade") || rest.equals("/bulk-retire")) {
                response.setStatus(HttpServletResponse.SC_OK);
                response.setContentType("application/json");
                response.setCharacterEncoding("UTF-8");
                response.getWriter().write(rest.equals("/bulk-grade") ? "{\"graded\":0}" : "{\"retired\":0}");
                return;
            }
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            response.setContentType("text/plain");
            response.getWriter().write(viewingAsOf ? "The sheet is shown as of " + asOf.trim() + "; it cannot be changed"
                    : archived ? "The sheet is archived" : "A viewer cannot change the sheet");
        }

        private static JsonNode parse(byte[] body) {
            if (body.length == 0) {
                return null;
            }
            try {
                JsonNode node = JSON.readTree(body);
                return node != null && node.isObject() ? node : null;
            } catch (IOException e) {
                return null;
            }
        }
    }

    /** The request with its body, already read, readable again by the endpoint. */
    private static final class Replay extends HttpServletRequestWrapper {
        private final byte[] body;

        Replay(HttpServletRequest request, byte[] body) {
            super(request);
            this.body = body;
        }

        @Override
        public ServletInputStream getInputStream() {
            ByteArrayInputStream in = new ByteArrayInputStream(body);
            return new ServletInputStream() {
                @Override
                public int read() {
                    return in.read();
                }

                @Override
                public int read(byte[] b, int off, int len) {
                    return in.read(b, off, len);
                }

                @Override
                public boolean isFinished() {
                    return in.available() == 0;
                }

                @Override
                public boolean isReady() {
                    return true;
                }

                @Override
                public void setReadListener(ReadListener listener) {
                    throw new UnsupportedOperationException();
                }
            };
        }

        @Override
        public BufferedReader getReader() {
            String encoding = getCharacterEncoding() == null ? "UTF-8" : getCharacterEncoding();
            return new BufferedReader(new InputStreamReader(getInputStream(), java.nio.charset.Charset.forName(encoding)));
        }

        @Override
        public int getContentLength() {
            return body.length;
        }

        @Override
        public long getContentLengthLong() {
            return body.length;
        }
    }
}
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.DelegationRepository;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** Lines that only report figures: never marked as made for a delegating steward. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");
    private static final Pattern HEAD = Pattern.compile("^(\\S+) sheet=(\\S+) by=(\\S+)");
    /** A name= or person= field: its value runs to the next field (a space then key=) or the end of the line. */
    private static final Pattern ABOUT = Pattern.compile(" (?:name|person)=(.*?)(?= [^\\s=]+=|$)");

    private final Path file;
    private final ObjectProvider<DelegationRepository> delegations;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path,
            ObjectProvider<DelegationRepository> delegations) {
        this.file = Path.of(path);
        this.delegations = delegations;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user acting as a
     *  steward by delegation (the sheet's today inside its range) ends with {@code for=<the delegating steward>}. */
    public synchronized void record(String entry) {
        Matcher m = HEAD.matcher(entry);
        if (m.find() && !FIGURES.contains(m.group(1))) {
            String steward = delegations.getObject().actingFor(m.group(2), m.group(3)).orElse(null);
            if (steward != null) {
                entry = entry + " for=" + steward;
            }
        }
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** The sheet's lines exactly as the file holds them, newest first. With a name (blank: every line), only the
     *  lines carrying name=<it> or person=<it>, compared as names are (case and surrounding spaces ignored). */
    public synchronized List<String> lines(String sheetId, String name) {
        String key = name.trim().toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        if (!Files.exists(file)) {
            return found;
        }
        List<String> all;
        try {
            all = Files.readAllLines(file, StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        for (String line : all) {
            Matcher head = HEAD.matcher(line);
            if (!head.find() || !head.group(2).equals(sheetId)) {
                continue;
            }
            if (key.isEmpty() || about(line, key)) {
                found.add(line);
            }
        }
        Collections.reverse(found);
        return found;
    }

    /** The lines about the person (see #lines) on the sheet they were transferred from to {@code to}, newest first,
     *  from the last PERSON_TRANSFERRED of them to that sheet back: what the sheet recorded about them while they were there. */
    public synchronized List<String> history(String fromSheet, String name, String to) {
        List<String> found = lines(fromSheet, name);
        for (int i = 0; i < found.size(); i++) {
            String line = found.get(i);
            Matcher head = HEAD.matcher(line);
            if (head.find() && head.group(1).equals("PERSON_TRANSFERRED")
                    && (line + " ").contains(" to=" + to + " ")) {
                return found.subList(i, found.size());
            }
        }
        return found;
    }

    private static boolean about(String line, String key) {
        Matcher m = ABOUT.matcher(line);
        while (m.find()) {
            if (m.group(1).trim().toLowerCase(Locale.ROOT).equals(key)) {
                return true;
            }
        }
        return false;
    }

    /** Remove the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
