/** Before a new today takes effect, writes SNAPSHOT for every person, in list order, with their due-total as it stood
 *  on the day being left — ahead of any period it closes and the figures it moves. A today equal to the stored one
 *  changes nothing and writes nothing. */
public class RecordSnapshot {
    public void record(@Val Sheet sheet, @Val LocalDate today, @Val TodayBy by, @Val RollupBefore before, Audit audit) {
        if (today.equals(sheet.today())) {
            return;
        }
        for (Figures f : before.figures().values()) {
            audit.record("SNAPSHOT sheet=" + sheet.id() + " by=" + by.by() + " name=" + f.name() + " due-total="
                    + f.dueTotal());
        }
    }
}
# PUT /api/sheets/{sheetId}/rates/{grade} — set a grade's rate, a percent with two decimals, from
# an optional from-date (none: from the beginning of time) through an optional to-date (none: no
# end), replacing any it had for that from-date. A grade other than A, B or C, a rate that is not a
# number 0.00 or more with up to two decimals, a from- or to-date that is not yyyy-MM-dd, or a
# to-date before the from-date, is a 400 and writes nothing. Responds with the
# rate as stored.
validate:
  class: net.officefloor.hq.app.rate.ValidateRate
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.rate.SaveRate
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.rate.RecordRateSet
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.rate.RespondWithRate

